window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-47287825f731df37"]={"versions": [{"id": "FIG-47287825f731df37", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptuelles Netzwerktopologie- und Terminologie-Strukturdiagramm (AUTOSAR Time Synchronization Architecture).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der hierarchischen Grundbegriffe und Topologie-Beziehungen für die zeitsynchrone Verteilung einer einheitlichen Zeitbasis über heterogene Kommunikationsmedien (CAN, FlexRay, Ethernet). Verortet im Kontext des Zusammenspiels zwischen dem <em>Synchronized Time-Base Manager</em> (StbM) und den busspezifischen Time-Sync-Modulen (<em>FrTSyn</em>, <em>CanTSyn</em>, <em>EthTSyn</em> gemäß RS_TS_20039, RS_TS_20043).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Time Domain (Zeitdomäne):</strong></li>\n<li>Dargestellt als äußere Begrenzung (violett gestrichelt).</li>\n<li>Repräsentiert die globale logische Domäne (<code>StbM_SynchronizedTimeBase</code>), innerhalb derer alle Knoten dieselbe Referenzzeit (Time Base ID) teilen (referenziert u. a. <code>ECUC_FrTSyn_00013</code>).</li>\n<li><strong>Time Subdomain (Teilzeitdomäne):</strong></li>\n<li>Ovale rote Gruppierungen.</li>\n<li>Beschreibt ein physikalisch homogenes Netzwerksegment bzw. einen Cluster (CAN, FR = FlexRay, ETH = Ethernet).</li>\n<li><strong>Global Time Master (GTM):</strong></li>\n<li>Oberste Instanz mit lokaler Referenzuhr (Clock-Icon, Master-Hardwareuhr).</li>\n<li>Besitzt die absolute Zeitautorität für die gesamte Time Domain (spezifischer Time Master ohne übergeordnete Synchronisationsquelle).</li>\n<li><strong>Time Master (TM):</strong></li>\n<li>Sendeknoten auf Subdomain-Ebene.</li>\n<li>Speist Zeitsynchronisationsnachrichten (Sync-PDUs) in das jeweilige Bussegment ein (<code>SWS_FrTSyn_00018</code>, <code>ECUC_FrTSyn_00014</code>).</li>\n<li><strong>Time Slave (TS):</strong></li>\n<li>Empfängerknoten auf Subdomain-Ebene.</li>\n<li>Synchronisiert seine lokale Zeitbasis auf die empfangenen Sync-PDUs des Masters (<code>SWS_FrTSyn_00019</code>).</li>\n<li><strong>Time Gateway (TG):</strong></li>\n<li>Hybride ECU-Entität mit Doppelrolle: Beinhaltet mindestens einen <em>Time Slave</em> (TS) zum Empfang der Zeitbasis aus einer übergeordneten Subdomain und einen <em>Time Master</em> (TM) zur Weitergabe in eine nachgelagerte Subdomain (<code>SWS_FrTSyn_00021</code>).</li>\n<li><strong>Time Communication Port:</strong></li>\n<li>Rot markierte physikalische bzw. logische Schnittstelle eines Steuergeräts an ein Netzwerksegment (entspricht dem BSW-Interface-Zugangspunkt, z. B. <code>FrIf</code>-Controller-Zuordnung für FrTSyn).</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li>$1$ Global Time Master pro Time Domain ($1:1$).</li>\n<li>$1$ Time Domain umfasst $n$ Time Subdomains ($1:n$).</li>\n<li>$1$ Time Subdomain umfasst genau $1$ aktiven Time Master (GTM oder TM) und $1..m$ Time Slaves ($1:m$).</li>\n<li>$1$ Time Gateway verbindet genau $1$ Quell-Subdomain mit $\\ge 1$ Ziel-Subdomains.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zeitursprung & PDU-Generierung (Top-Level):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der GTM liest periodisch die Master-Uhr (<code>StbM_GetCurrentTime</code>) und generiert Master-Sync-PDUs für die primären Bussegmente (CAN, FlexRay, Ethernet).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subdomain-Austausch (FlexRay-spezifisch via FrTSyn):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>FrTSyn TM</em> überträgt Sync-PDUs innerhalb des FlexRay-Kommunikationszyklus (statisches oder dynamisches Segment) über <code>FrIf_Transmit</code>.</li>\n<li><em>FrTSyn TS</em> empfängt die PDUs via <code>FrIf_RxIndication</code>, extrahiert Zeitstempel und Zykluskorrekturdaten und übergibt diese via <code>StbM_BusSetGlobalTime</code> an den lokalen StbM.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Gateway-Bridging (TG-Dynamik):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner Zwischenschritt im TG: Empfang über Quell-TS (z. B. FR oder ETH), Aktualisierung der StbM-Zeitbasis im Gateway, Kompensation der internen Verweilzeit (Gateway Latency Correction).</li>\n<li>Weiterleitung: Der lokale TM-Port (z. B. CAN) triggert die Aussendung neuer Zeit-PDUs auf das untergeordnete Segment.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehler- und Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausbleiben von Sync-Nachrichten führt zum Timeout im TS (<code>FrTSynGlobalTimeSlaveTimeout</code>, <code>StbM_TimeBaseStatusType::TIMEOUT_BIT</code>).</li>\n<li>Bei Synchronisationsverlust im TG wird der Status <code>SYNC_TO_GATEWAY</code> de-assertiert; unterlagerte TMs signalisieren den Verlust der synchronen Referenz im Protokoll-Header.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ECUC / ARXML):</strong></li>\n<li><code>ECUC_FrTSyn_00013</code> (<code>FrTSynGlobalTimeDomainId</code>): Eindeutige Domänen-ID ($0..15$).</li>\n<li><code>ECUC_FrTSyn_00014</code>: Konfiguration der Knotenrolle (<code>FrTSynGlobalTimeMaster</code> vs. <code>FrTSynGlobalTimeSlave</code>). Gateway-Knoten benötigen getrennte TSyn-Instanzen/Cluster-Zuweisungen im BSW-Stack, verknüpft über denselben <code>StbMSynchronizedTimeBase</code>-Index.</li>\n<li><strong>FlexRay-Spezifika:</strong></li>\n<li>Die FrTSyn-Zeitsynchronisation agiert auf der logischen AUTOSAR-Ebene und ist strikt zu unterscheiden von der intrinsischen FlexRay-Cluster-Taktsynchronisation (Macrotick/Microtick). FrTSyn synchronisiert globale Absolutzeit (z. B. UTC/TAI oder fahrzeugweites Zeitraster).</li>\n<li><strong>Gateway-Laufzeitkompensation:</strong></li>\n<li>Gemäß <code>SWS_FrTSyn_00021</code> muss die Verweilzeit innerhalb des TG präzise erfasst und in das Zeit-Korrekturfeld (<code>UserByte</code> / Sequence Counter / Nanosekunden-Offset) eingerechnet werden, um Jitter-Akkumulation über Busgrenzen hinweg zu minimieren.</li>\n</ul>"}, {"id": "FIG-b4ce7bf9ee68a1c9", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptuelles Netzwerktopologie- und Terminologie-Strukturdiagramm (AUTOSAR Time Synchronization Architecture).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der hierarchischen Grundbegriffe und Topologie-Beziehungen für die zeitsynchrone Verteilung einer einheitlichen Zeitbasis über heterogene Kommunikationsmedien (CAN, FlexRay, Ethernet). Verortet im Kontext des Zusammenspiels zwischen dem <em>Synchronized Time-Base Manager</em> (StbM) und den busspezifischen Time-Sync-Modulen (<em>FrTSyn</em>, <em>CanTSyn</em>, <em>EthTSyn</em> gemäß RS_TS_20039, RS_TS_20043).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Time Domain (Zeitdomäne):</strong></li>\n<li>Dargestellt als äußere Begrenzung (violett gestrichelt).</li>\n<li>Repräsentiert die globale logische Domäne (<code>StbM_SynchronizedTimeBase</code>), innerhalb derer alle Knoten dieselbe Referenzzeit (Time Base ID) teilen (referenziert u. a. <code>ECUC_FrTSyn_00013</code>).</li>\n<li><strong>Time Subdomain (Teilzeitdomäne):</strong></li>\n<li>Ovale rote Gruppierungen.</li>\n<li>Beschreibt ein physikalisch homogenes Netzwerksegment bzw. einen Cluster (CAN, FR = FlexRay, ETH = Ethernet).</li>\n<li><strong>Global Time Master (GTM):</strong></li>\n<li>Oberste Instanz mit lokaler Referenzuhr (Clock-Icon, Master-Hardwareuhr).</li>\n<li>Besitzt die absolute Zeitautorität für die gesamte Time Domain (spezifischer Time Master ohne übergeordnete Synchronisationsquelle).</li>\n<li><strong>Time Master (TM):</strong></li>\n<li>Sendeknoten auf Subdomain-Ebene.</li>\n<li>Speist Zeitsynchronisationsnachrichten (Sync-PDUs) in das jeweilige Bussegment ein (<code>SWS_FrTSyn_00018</code>, <code>ECUC_FrTSyn_00014</code>).</li>\n<li><strong>Time Slave (TS):</strong></li>\n<li>Empfängerknoten auf Subdomain-Ebene.</li>\n<li>Synchronisiert seine lokale Zeitbasis auf die empfangenen Sync-PDUs des Masters (<code>SWS_FrTSyn_00019</code>).</li>\n<li><strong>Time Gateway (TG):</strong></li>\n<li>Hybride ECU-Entität mit Doppelrolle: Beinhaltet mindestens einen <em>Time Slave</em> (TS) zum Empfang der Zeitbasis aus einer übergeordneten Subdomain und einen <em>Time Master</em> (TM) zur Weitergabe in eine nachgelagerte Subdomain (<code>SWS_FrTSyn_00021</code>).</li>\n<li><strong>Time Communication Port:</strong></li>\n<li>Rot markierte physikalische bzw. logische Schnittstelle eines Steuergeräts an ein Netzwerksegment (entspricht dem BSW-Interface-Zugangspunkt, z. B. <code>FrIf</code>-Controller-Zuordnung für FrTSyn).</li>\n<li><strong>Kardinalitäten & Beziehungen:</strong></li>\n<li>$1$ Global Time Master pro Time Domain ($1:1$).</li>\n<li>$1$ Time Domain umfasst $n$ Time Subdomains ($1:n$).</li>\n<li>$1$ Time Subdomain umfasst genau $1$ aktiven Time Master (GTM oder TM) und $1..m$ Time Slaves ($1:m$).</li>\n<li>$1$ Time Gateway verbindet genau $1$ Quell-Subdomain mit $\\ge 1$ Ziel-Subdomains.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zeitursprung & PDU-Generierung (Top-Level):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der GTM liest periodisch die Master-Uhr (<code>StbM_GetCurrentTime</code>) und generiert Master-Sync-PDUs für die primären Bussegmente (CAN, FlexRay, Ethernet).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subdomain-Austausch (FlexRay-spezifisch via FrTSyn):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>FrTSyn TM</em> überträgt Sync-PDUs innerhalb des FlexRay-Kommunikationszyklus (statisches oder dynamisches Segment) über <code>FrIf_Transmit</code>.</li>\n<li><em>FrTSyn TS</em> empfängt die PDUs via <code>FrIf_RxIndication</code>, extrahiert Zeitstempel und Zykluskorrekturdaten und übergibt diese via <code>StbM_BusSetGlobalTime</code> an den lokalen StbM.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Gateway-Bridging (TG-Dynamik):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner Zwischenschritt im TG: Empfang über Quell-TS (z. B. FR oder ETH), Aktualisierung der StbM-Zeitbasis im Gateway, Kompensation der internen Verweilzeit (Gateway Latency Correction).</li>\n<li>Weiterleitung: Der lokale TM-Port (z. B. CAN) triggert die Aussendung neuer Zeit-PDUs auf das untergeordnete Segment.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehler- und Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausbleiben von Sync-Nachrichten führt zum Timeout im TS (<code>FrTSynGlobalTimeSlaveTimeout</code>, <code>StbM_TimeBaseStatusType::TIMEOUT_BIT</code>).</li>\n<li>Bei Synchronisationsverlust im TG wird der Status <code>SYNC_TO_GATEWAY</code> de-assertiert; unterlagerte TMs signalisieren den Verlust der synchronen Referenz im Protokoll-Header.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ECUC / ARXML):</strong></li>\n<li><code>ECUC_FrTSyn_00013</code> (<code>FrTSynGlobalTimeDomainId</code>): Eindeutige Domänen-ID ($0..15$).</li>\n<li><code>ECUC_FrTSyn_00014</code>: Konfiguration der Knotenrolle (<code>FrTSynGlobalTimeMaster</code> vs. <code>FrTSynGlobalTimeSlave</code>). Gateway-Knoten benötigen getrennte TSyn-Instanzen/Cluster-Zuweisungen im BSW-Stack, verknüpft über denselben <code>StbMSynchronizedTimeBase</code>-Index.</li>\n<li><strong>FlexRay-Spezifika:</strong></li>\n<li>Die FrTSyn-Zeitsynchronisation agiert auf der logischen AUTOSAR-Ebene und ist strikt zu unterscheiden von der intrinsischen FlexRay-Cluster-Taktsynchronisation (Macrotick/Microtick). FrTSyn synchronisiert globale Absolutzeit (z. B. UTC/TAI oder fahrzeugweites Zeitraster).</li>\n<li><strong>Gateway-Laufzeitkompensation:</strong></li>\n<li>Gemäß <code>SWS_FrTSyn_00021</code> muss die Verweilzeit innerhalb des TG präzise erfasst und in das Zeit-Korrekturfeld (<code>UserByte</code> / Sequence Counter / Nanosekunden-Offset) eingerechnet werden, um Jitter-Akkumulation über Busgrenzen hinweg zu minimieren.</li>\n</ul>"}], "trans": [{"from": "FIG-47287825f731df37", "to": "FIG-b4ce7bf9ee68a1c9", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
